local FONT = "assets/font/DialogFont.ttf"
local function makeText(size)
    local lb = Label(FONT, size)
    if lb == nil then
        lb = Label("sarasa-mono-sc-regular", size)
    end
    return lb
end
local PHASE_NAMES = {
    "朔",
    "眉月",
    "上弦",
    "盈凸",
    "望",
    "亏凸",
    "下弦",
    "残月"
}
local PANEL_DARK = {r = 14, g = 17, b = 22, a = 255}
local function col(c)
    return Color(c.r, c.g, c.b, c.a)
end
--- 圆弧折线点集（角度制，y 向上）
local function circlePts(cx, cy, r, a0, a1, steps)
    local pts = {}
    do
        local i = 0
        while i <= steps do
            local a = (a0 + (a1 - a0) * i / steps) * Math.PI / 180
            pts:push(Vec2(
                cx + Math:cos(a) * r,
                cy + Math:sin(a) * r
            ))
            i = i + 1
        end
    end
    return pts
end
local function phaseName(phase)
    return phase >= 0 and phase < #PHASE_NAMES and PHASE_NAMES[phase + 1] or ""
end
