function TreeOverlay.prototype.open(self, system)
    self.source = system
    self.openFlag = true
    self.root.visible = true
    self.hit.touchEnabled = true
    self:render(system)
end
function TreeOverlay.prototype.close(self)
    self.openFlag = false
    self.root.visible = false
    self.hit.touchEnabled = false
end
function TreeOverlay.prototype.toggle(self, system)
