    self:computeLayout(system)
    self.treeDraw:clear()
    self:drawBranches(system)
    self:drawMoons(system)
    self:updateLabels(system)
    if self.statsLb ~= nil then
        self.statsLb.text = system:getStats() .. "　·　本树只增不减"
    end
end
function TreeOverlay.prototype.computeLayout(self, system)
    local pts = {}
    local maxDepth = 0
    do
        local i = 0
        while i < #system.nodes do
            if system.nodes[i + 1].depth > maxDepth then
                maxDepth = system.nodes[i + 1].depth
            end
            i = i + 1
        end
    end
    local yBot = -self.h / 2 + 120
    local yTop = self.h / 2 - 150
    local rows = maxDepth + 1
    local rowH = rows <= 1 and 0 or Math:min(120, (yTop - yBot) / (rows - 1))
    local groups = {}
    do
        local d = 0
        while d <= maxDepth do
            groups:push({})
            d = d + 1
        end
    end
    do
        local i = 0
        while i < #system.nodes do
            local n = system.nodes[i + 1]
            local d = Math:max(
                0,
                Math:min(maxDepth, n.depth)
            )
            groups[d + 1]:push(n)
            i = i + 1
        end
    end
    do
        local d = 0
        while d < #groups do
            local g = groups[d + 1]
            local n = #g
            local spacing = Math:min(
                150,
                (self.w - 220) / Math:max(1, n)
            )
            do
                local i = 0
                while i < n do
                    pts:push({id = g[i + 1].id, x = (i - (n - 1) / 2) * spacing, y = yBot + d * rowH})
                    i = i + 1
                end
            end
            d = d + 1
        end
    end
    self.layout = pts
end
