function TreeOverlay.prototype.drawMoonShape(self, x, y, r, phase, abandoned)
    local lit = abandoned and col(Palette.paleInkFar) or col(Palette.moonWhite)
    local rim = abandoned and col(Palette.paleInkFar) or col(Palette.moonCyanSoft)
    local dark = col(PANEL_DARK)
    if phase == 0 then
        self.treeDraw:drawPolygon(
            circlePts(
                x,
                y,
                r,
                0,
                360,
                24
            ),
            ink(0, 0, 0, 0),
            2,
            rim
        )
        return
    end
    if phase == 1 or phase == 7 then
        local s = phase == 1 and 1 or -1
        local pts = circlePts(
            x,
            y,
            r,
            s == 1 and -75 or 105,
            s == 1 and 75 or 255,
            12
        ):concat(circlePts(
            x - s * r * 0.5,
            y,
            r * 0.9,
            s == 1 and 75 or 255,
            s == 1 and -75 or 105,
            12
        ))
        self.treeDraw:drawPolygon(pts, lit, 1, rim)
        return
    end
    if phase == 2 or phase == 6 then
        local pts = circlePts(
            x,
            y,
            r,
            phase == 2 and -90 or 90,
            phase == 2 and 90 or 270,
            12
        ):concat({Vec2(x, y)})
        self.treeDraw:drawPolygon(pts, lit, 1, rim)
        return
    end
    if phase == 3 or phase == 5 then
        self.treeDraw:drawPolygon(
            circlePts(
                x,
                y,
                r,
                0,
                360,
                24
            ),
            lit,
            1,
            rim
        )
        self.treeDraw:drawDot(
            Vec2(x + (phase == 3 and -r * 0.8 or r * 0.8), y),
            r * 0.62,
            dark
        )
        return
    end
    self.treeDraw:drawPolygon(
        circlePts(
            x,
            y,
            r,
            0,
            360,
            24
        ),
        lit,
        1,
        rim
    )
end
function TreeOverlay.prototype.updateLabels(self, system)
