        lb.anchor = Vec2(0.5, 1)
        lb:addTo(self.root)
        self.viaLbs:push(lb)
    end
    do
        local i = 0
        while i < #self.viaLbs do
            self.viaLbs[i + 1].visible = false
            i = i + 1
        end
    end
    do
        local i = 0
        while i < count do
            do
