                lb.text = (phaseName(n.phase) .. " · ") .. n.via
                lb.position = Vec2(p.x, p.y - 20)
                lb.color = n.id == system.currentId and col(Palette.gold) or (n.abandoned and col(Palette.paleInkFar) or col(Palette.paleInk))
