            ::__continue63::
            i = i + 1
        end
    end
end
function TreeOverlay.prototype.jumpToNode(self, system, id)
    if id == system.currentId then
        return
    end
    if system.onJumpTo ~= nil then
        system:onJumpTo(id)
    end
    system:jumpTo(id)
    self:render(system)
end
